        List<Integer> nums = (List<Integer>) data.get("nums");
        if (nums == null || nums.isEmpty()) return 0;

        int count = 0;
        for (int i = 0; i < nums.size() - 1; i++) { // Iterate up to the second last element
            for (int j = i + 1; j < nums.size(); j++) {
                if (nums.get(i) > nums.get(j)) {
                    count++;
                }
            }
        }

        return count;
    }
}

