        int count = 0;
        for (int i = 0; i < nums.size() - 1; i++) { // Changed the condition to avoid out-of-bounds error
            for (int j = i + 1; j < nums.size(); j++) {
                if (nums.get(i) > nums.get(j)) {
                    count++;
                }
            }
        }
        return count;
    }

    public static void main(String[] args) {
        System.out.println(solve(Collections.singletonMap("nums", new ArrayList<>())));
